WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at NULLS LAST, id) AS dedup_rank FROM sessions) ranked WHERE dedup_rank = 1) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, (SELECT MIN(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS min_account_balance FROM deduped s ORDER BY country DESC, min_account_balance
